export class BoatChumRenderer {
  #surface;
  #primitives;

  constructor({ surface, primitives }) {
    if (!surface || typeof surface.ellipse !== "function") {
      throw new TypeError("BoatChumRenderer requires surface");
    }
    if (
      !primitives ||
      typeof primitives.beginClip !== "function" ||
      typeof primitives.endClip !== "function"
    ) {
      throw new TypeError("BoatChumRenderer requires primitives");
    }
    this.#surface = surface;
    this.#primitives = primitives;
  }

  render(model) {
    if (!model.visible) return;
    this.#renderChumZones(model);
    this.#renderWaypoints(model);
    this.#renderWake(model);
    this.#renderBoats(model);
    this.#renderSensors(model);
    this.#renderRoute(model);
  }

  #renderRoute(model) {
    if (model.boatRoute.count === 0) return;
    const surface = this.#surface;
    surface.save();
    surface.lineWidth = 2;
    surface.strokeStyle = "rgba(0, 220, 255, 0.85)";
    surface.beginPath();
    for (let index = 0; index < model.boatRoute.count; index += 1) {
      const dash = model.boatRoute.getAt(index);
      surface.moveTo(dash.startX, dash.startY);
      surface.lineTo(dash.endX, dash.endY);
    }
    surface.stroke();
    surface.restore();
  }

  #renderChumZones(model) {
    const clipped = this.#primitives.beginClip(model.clipRegions);
    for (let index = 0; index < model.chumZones.count; index += 1) {
      const zone = model.chumZones.getAt(index);
      const surface = this.#surface;
      surface.save();
      surface.beginPath();
      surface.ellipse(zone.x, zone.y, zone.radiusX, zone.radiusY, 0, 0, Math.PI * 2);
      surface.fillStyle = `rgba(200, 255, 100, ${zone.opacity * 0.2})`;
      surface.fill();
      surface.strokeStyle = `rgba(200, 255, 100, ${zone.opacity * 0.5})`;
      surface.lineWidth = 2;
      surface.stroke();
      surface.restore();
    }
    this.#primitives.endClip(clipped);
  }

  #renderWaypoints(model) {
    for (let index = 0; index < model.waypoints.count; index += 1) {
      const waypoint = model.waypoints.getAt(index);
      const surface = this.#surface;
      surface.save();
      surface.beginPath();
      surface.arc(
        waypoint.x,
        waypoint.y,
        8 * waypoint.scale,
        0,
        Math.PI * 2,
      );
      surface.strokeStyle = "rgba(255, 170, 0, 0.6)";
      surface.lineWidth = Math.max(1, 2 * waypoint.scale);
      surface.stroke();
      surface.beginPath();
      surface.arc(
        waypoint.x,
        waypoint.y,
        3 * waypoint.scale,
        0,
        Math.PI * 2,
      );
      surface.fillStyle = "#ffaa00";
      surface.fill();
      if (waypoint.showIndex) {
        surface.fillStyle = "#ffffff";
        surface.font = `bold ${Math.max(6, 10 * waypoint.scale)}px Arial`;
        surface.fillText(
          String(waypoint.index),
          waypoint.x + 10 * waypoint.scale,
          waypoint.y + 4 * waypoint.scale,
        );
      }
      surface.restore();
    }
  }

  // Spec 155: the procedural wake under the boats (the scene draws soft foam sprites; here plain translucent dots).
  #renderWake(model) {
    if (model.boatWake.count === 0) return;
    const surface = this.#surface;
    surface.save();
    for (let index = 0; index < model.boatWake.count; index += 1) {
      const puff = model.boatWake.getAt(index);
      surface.fillStyle = `rgba(255, 255, 255, ${puff.alpha * 0.6})`;
      surface.beginPath();
      surface.arc(puff.x, puff.y, puff.size / 2, 0, Math.PI * 2);
      surface.fill();
    }
    surface.restore();
  }

  #renderBoats(model) {
    const surface = this.#surface;
    surface.save();
    surface.textAlign = "center";
    surface.textBaseline = "middle";
    for (let index = 0; index < model.boats.count; index += 1) {
      const boat = model.boats.getAt(index);
      surface.save();
      surface.translate(boat.x, boat.y);
      surface.rotate(boat.angle + Math.PI);
      surface.font = `${boat.fontSize}px sans-serif`;
      surface.fillText(boat.emoji, 0, 0);
      surface.restore();
      surface.fillStyle = "rgba(0, 0, 0, 0.7)";
      surface.fillRect(
        boat.x - boat.barWidth / 2,
        boat.y + boat.barY,
        boat.barWidth,
        boat.barHeight,
      );
      surface.fillStyle = boat.energyColor;
      surface.fillRect(
        boat.x - boat.barWidth / 2,
        boat.y + boat.barY,
        boat.barWidth * boat.energyRatio,
        boat.barHeight,
      );
    }
    surface.restore();
  }

  #renderSensors(model) {
    const surface = this.#surface;
    surface.save();
    surface.lineWidth = 2;
    for (let index = 0; index < model.sensorRays.count; index += 1) {
      const ray = model.sensorRays.getAt(index);
      surface.strokeStyle = ray.blocked
        ? "rgba(255, 0, 0, 0.6)"
        : "rgba(0, 255, 0, 0.6)";
      surface.beginPath();
      surface.moveTo(ray.startX, ray.startY);
      surface.lineTo(ray.endX, ray.endY);
      surface.stroke();
    }
    surface.restore();
  }
}
