export class MutableFightFrameContext {
  constructor() {
    this.floatEntity = null;
    this.bounds = null;
    this.waterMetric = null;
    this.input = null;
    this.rodMotion = null;
    this.env = null;
    this.getRodVirtualPos = null;
    this.getBaseRodVirtualPos = null;
    this.getScreenOffsetRatio = null;
    this.rodControlCastAnchor = null;
    this.checkWater = null;
    this.net = null;
    this.fishData = null;
  }

  reset() {
    this.rodMotion = null;
    this.floatEntity = null;
    this.bounds = null;
    this.waterMetric = null;
    this.input = null;
    this.env = null;
    this.net = null;
    this.fishData = null;
    this.rodControlCastAnchor = null;
  }

  setBounds(bounds) {
    this.bounds = bounds;
  }

  setEnvironment(env) {
    this.env = env;
  }
}
