import { INVENTORY_SECTIONS } from "./inventory_sections.js";
import { INVENTORY_SORT_CONFIG } from "./inventory_sort_config.js";

export class InventoryViewModelNormalizer {
  #sortDefaults;

  static MAIN_SLOT_IDS = Object.freeze([
    "rod",
    "reel",
    "terminalLine",
    "tackle",
    "float",
  ]);

  static AUXILIARY_SLOT_IDS = Object.freeze([
    "net",
    "handChum",
    "delivery",
    "gasMask",
    "radio",
  ]);

  constructor({
    sortConfig = INVENTORY_SORT_CONFIG,
  } = {}) {
    this.#sortDefaults = Object.freeze({
      criterionIds: Object.freeze([
        ...(sortConfig?.defaults?.criterionIds || ["rarity"]),
      ]),
      directionId: String(sortConfig?.defaults?.directionId || "descending"),
    });
  }

  normalize(source = {}) {
    const panel = source.panel || {};
    const requestedMode = panel.mode || source.mode;
    const mode = ["assembly", "saved-loadout"].includes(requestedMode) ? requestedMode : "loadout";

    return Object.freeze({
      isOpen: source.isOpen !== false,
      equipmentFeedback: source.equipmentFeedback || null,
      sections: Object.freeze({ activeId: INVENTORY_SECTIONS.items.some((section) => section.id === source.sections?.activeId)
        ? source.sections.activeId : INVENTORY_SECTIONS.defaultSectionId,
        backpackItemCount: this.#finite(source.sections?.backpackItemCount, 0) }),
      header: this.#normalizeHeader(source.header),
      settings: this.#normalizeSettings(source.settings),
      tooltipContext: this.#normalizeTooltipContext(source.tooltipContext),
      panel: Object.freeze({
        mode,
        savedLoadout: this.#normalizeSavedLoadout(panel.savedLoadout || source.inventory?.savedLoadout),
        loadout: this.#normalizeLoadout(panel.loadout || source.loadout),
        assembly: this.#normalizeAssembly(
          panel.assembly || source.assembly,
        ),
      }),
      inventory: this.#normalizeInventory(source.inventory),
    });
  }

  #normalizeHeader(source = {}) {
    const activeTackle = source.activeTackle || {};
    return Object.freeze({
      loadLabel: this.#text(source.loadLabel, "Макс. навантаження снасті"),
      loadValue: this.#finite(source.loadValue, 0),
      loadUnit: this.#text(source.loadUnit, "кг"),
      activeBaits: this.#array(activeTackle.baits || source.activeBaits),
      activeChums: this.#array(activeTackle.chums || source.activeChums),
      baitSlots: this.#normalizeConsumableSlots(source.baitSlots, activeTackle.baits || source.activeBaits),
      chumSlots: this.#normalizeConsumableSlots(source.chumSlots, activeTackle.chums || source.activeChums),
      baitStock: Math.max(0, Math.floor(this.#finite(source.refillStock?.bait ?? source.baitStock, 0))),
      chumStock: Math.max(0, Math.floor(this.#finite(source.refillStock?.chum ?? source.chumStock, 0))),
    });
  }

  #normalizeConsumableSlots(slots, items) {
    const source = Array.isArray(slots) ? slots : this.#array(items).map((item) => ({ item, available: true }));
    return Object.freeze(source.map((slot, slotIndex) => Object.freeze({
      slotIndex, available: slot.available === true, highlighted: slot.highlighted === true, item: slot.item || null,
      stock: Math.max(0, Math.floor(this.#finite(slot.stock, 0))),
      showCount: slot.showCount !== false,
    })));
  }

  #normalizeSettings(source = {}) {
    return Object.freeze({
      autoBait: source.autoBait === true,
      autoChum: source.autoChum === true,
    });
  }

  #normalizeTooltipContext(source = {}) {
    return Object.freeze({
      rodType: this.#text(source.rodType, ""),
      rodHasReel:
        typeof source.rodHasReel === "boolean" ? source.rodHasReel : null,
      availableCapabilities: Object.freeze(
        this.#array(source.availableCapabilities).filter(
          (value) => typeof value === "string" && value.trim(),
        ),
      ),
      equipment: Object.freeze({
        ...(source.equipment && typeof source.equipment === "object"
          ? source.equipment
          : {}),
      }),
    });
  }

  #normalizeLoadout(source = {}) {
    const mainSlots = this.#normalizeSlots(source.mainSlots, "equipment");
    const orderedSlots = this.#orderMainSlots(mainSlots);
    return Object.freeze({
      mainSlots: Object.freeze(orderedSlots),
      auxiliarySlots: Object.freeze(
        this.#orderSlots(
          this.#normalizeSlots(source.auxiliarySlots, "auxiliary"),
          InventoryViewModelNormalizer.AUXILIARY_SLOT_IDS,
        ),
      ),
    });
  }

  #normalizeAssembly(source = {}) {
    return Object.freeze({
      root: source.root || null,
      rootLabel: this.#text(source.rootLabel, source.root?.name || "Предмет"),
      rootInstanceId: this.#text(
        source.rootInstanceId,
        source.root?.instanceId || "",
      ),
      sockets: Object.freeze(this.#normalizeSlots(source.sockets, "socket")),
      parameterItems: Object.freeze(this.#array(source.parameterItems)),
      equipped: source.equipped === true,
      rodRemovalStep: source.rodRemovalStep || null,
      canEquip: source.canEquip !== false,
      showEquip: source.showEquip !== false && source.equipped !== true,
      canUnequip: source.canUnequip !== false,
      showUnequip: source.showUnequip !== false,
      canDisassemble: source.canDisassemble !== false,
      showDisassemble: source.showDisassemble !== false,
      equipWarning: this.#text(source.equipWarning, ""),
      unequipWarning: this.#text(source.unequipWarning, ""),
      disassembleWarning: this.#text(source.disassembleWarning, ""),
    });
  }

  #normalizeSavedLoadout(source = {}) {
    return Object.freeze({
      loadoutId: this.#text(source.loadoutId, ""),
      name: this.#text(source.name, "Збірка"),
      card: source.card || null,
      slots: Object.freeze(this.#normalizeSlots(source.slots, "saved-loadout")),
      canEquipAll: source.canEquipAll !== false,
      equipWarning: this.#text(source.equipWarning, ""),
    });
  }

  #normalizeInventory(source = {}) {
    const categories = this.#array(source.categories).map((category) =>
      Object.freeze({
        id: this.#text(category?.id, "all"),
        label: this.#text(category?.label, "Усі"),
        icon: this.#text(category?.icon, ""),
        iconAsset: this.#text(category?.iconAsset, ""),
        selected:
          category?.selected === true ||
          category?.id === source.activeCategoryId,
      }),
    );
    const subfilters = this.#array(source.subfilters).map((filter) =>
      Object.freeze({
        id: this.#text(filter?.id, "filter"),
        label: this.#text(filter?.label, "Фільтр"),
        count: Math.max(0, Math.floor(this.#finite(filter?.count, 0))),
        selected:
          filter?.selected === true ||
          this.#array(source.activeSubfilterIds).includes(filter?.id),
      }),
    );
    const sort = this.#normalizeSort(source.sort);
    return Object.freeze({
      mode: source.mode === "saved-loadout" ? "saved-loadout" : "inventory",
      savedLoadout: this.#normalizeSavedLoadout(source.savedLoadout),
      categories: Object.freeze(categories),
      subfilters: Object.freeze(subfilters),
      sort,
      activeSubfilterIds: Object.freeze(
        this.#array(source.activeSubfilterIds).filter(
          (value) => typeof value === "string" && value.trim(),
        ),
      ),
      items: Object.freeze(this.#array(source.items)),
      selectedInstanceId: this.#text(source.selectedInstanceId, ""),
      highlightedSlotId: this.#text(source.highlightedSlotId, ""),
      emptyMessage: this.#text(source.emptyMessage, "Інвентар порожній"),
    });
  }

  #normalizeSort(source = {}) {
    const requestedCriterionIds = Array.isArray(source.criterionIds)
      ? source.criterionIds
      : source.criterionId
        ? [source.criterionId]
        : this.#sortDefaults.criterionIds;
    const criterionIds = Object.freeze([
      ...new Set(
        requestedCriterionIds
          .filter((value) => typeof value === "string" && value.trim())
          .map((value) => value.trim()),
      ),
    ]);
    const directionId = this.#text(
      source.directionId,
      this.#sortDefaults.directionId,
    );
    const activeRarityIds = this.#array(source.activeRarityIds).filter(
      (value) => typeof value === "string" && value.trim(),
    );
    return Object.freeze({
      criterionIds,
      directionId,
      criteria: Object.freeze(
        this.#array(source.criteria).map((criterion) => {
          const id = this.#text(criterion?.id, "type");
          const priorityIndex = criterionIds.indexOf(id);
          return Object.freeze({
            id,
            label: this.#text(criterion?.label, "Сортування"),
            selected: priorityIndex >= 0,
            priority: priorityIndex >= 0 ? priorityIndex + 1 : null,
          });
        }),
      ),
      directions: Object.freeze(
        this.#array(source.directions).map((direction) =>
          Object.freeze({
            id: this.#text(direction?.id, "ascending"),
            icon: this.#text(direction?.icon, "↕"),
            label: this.#text(direction?.label, "Напрямок"),
            selected:
              direction?.selected === true || direction?.id === directionId,
          }),
        ),
      ),
      rarities: Object.freeze(
        this.#array(source.rarities).map((rarity) =>
          Object.freeze({
            id: this.#text(rarity?.id, "common"),
            label: this.#text(rarity?.label, "Рідкість"),
            color: this.#text(rarity?.color, "rgb(145, 150, 160)"),
            count: Math.max(0, Math.floor(this.#finite(rarity?.count, 0))),
            selected:
              rarity?.selected === true || activeRarityIds.includes(rarity?.id),
          }),
        ),
      ),
      activeRarityIds: Object.freeze(activeRarityIds),
    });
  }

  #normalizeSlots(slots, context) {
    return this.#array(slots)
      .filter((slot) => slot?.visible !== false)
      .map((slot, index) => {
        const item = slot.item || null;
        const state = this.#resolveSlotState(slot, item);
        return Object.freeze({
          ...slot,
          slotId: this.#text(slot.slotId || slot.id, `${context}-${index}`),
          socketId: this.#text(
            slot.socketId,
            slot.slotId || slot.id || `${context}-${index}`,
          ),
          label: this.#text(slot.label, "Комірка"),
          item,
          state,
          warning: this.#text(
            slot.warning,
            state === "locked"
              ? "Ще не розблоковано"
              : state === "unavailable"
                ? "Немає відповідного предмета"
                : "",
          ),
          highlighted: slot.highlighted === true,
          compatibleItems: Object.freeze(this.#array(slot.compatibleItems)),
          canSelectCompatibleItem: slot.canSelectCompatibleItem === true,
        });
      });
  }

  #resolveSlotState(slot, item) {
    if (item) return "filled";
    const state = String(slot.state || slot.availability || "available");
    if (state === "locked") return "locked";
    if (
      state === "unavailable" ||
      state === "no-item" ||
      state === "missing"
    ) {
      return "unavailable";
    }
    return "available";
  }

  #orderMainSlots(slots) {
    return this.#orderSlots(
      slots,
      InventoryViewModelNormalizer.MAIN_SLOT_IDS,
    );
  }

  #orderSlots(slots, orderedIds) {
    const positions = new Map(
      orderedIds.map((id, index) => [id, index]),
    );
    return slots.slice().sort((left, right) => {
      const leftPosition = positions.get(left.slotId) ?? Number.MAX_SAFE_INTEGER;
      const rightPosition =
        positions.get(right.slotId) ?? Number.MAX_SAFE_INTEGER;
      return leftPosition - rightPosition;
    });
  }

  #array(value) {
    return Array.isArray(value) ? value.filter(Boolean) : [];
  }

  #text(value, fallback) {
    return typeof value === "string" && value.trim() ? value : fallback;
  }

  #finite(value, fallback) {
    const number = Number(value);
    return Number.isFinite(number) ? number : fallback;
  }
}
