import { nonNegativeOr } from "../../../../engine/math/number_normalization.js";

export class PlayerPressureFatigueSourceResolver {
  #config;

  constructor(config = {}) {
    this.#config = config || {};
  }

  resolve({
    reelHoldActive = false,
    reelHoldSessionActive = false,
    rodHoldActive = false,
    controlActive = false,
    effectivePressureKg = 0,
    config = null,
  } = {}) {
    const cfg = config || this.#config || {};
    const source = cfg.source || {};
    const enabled = cfg.enabled === true;
    const sourceMode = source.mode || "reel_hold_session";

    if (!enabled) {
      return this.#frame({
        sourceMode,
        active: false,
        reason: "disabled",
        reelHoldActive,
        reelHoldSessionActive,
        rodHoldActive,
        controlActive,
        effectivePressureKg,
      });
    }

    if (sourceMode === "reel_hold") {
      const active = reelHoldActive === true;
      return this.#frame({
        sourceMode,
        active,
        reason: active ? "reel_hold_active" : "reel_hold_inactive",
        reelHoldActive,
        reelHoldSessionActive,
        rodHoldActive,
        controlActive,
        effectivePressureKg,
      });
    }

    if (sourceMode === "reel_hold_session") {
      const active = reelHoldSessionActive === true;
      return this.#frame({
        sourceMode,
        active,
        reason: active
          ? "reel_hold_session_active"
          : "reel_hold_session_inactive",
        reelHoldActive,
        reelHoldSessionActive,
        rodHoldActive,
        controlActive,
        effectivePressureKg,
      });
    }

    return this.#frame({
      sourceMode,
      active: false,
      reason: "unsupported_source_mode",
      reelHoldActive,
      reelHoldSessionActive,
      rodHoldActive,
      controlActive,
      effectivePressureKg,
    });
  }

  #frame({
    sourceMode,
    active,
    reason,
    reelHoldActive,
    reelHoldSessionActive,
    rodHoldActive,
    controlActive,
    effectivePressureKg,
  }) {
    return Object.freeze({
      source: "player_pressure_fatigue_source",
      sourceMode,
      active: active === true,
      reason,
      reelHoldActive: reelHoldActive === true,
      reelHoldSessionActive: reelHoldSessionActive === true,
      rodHoldActive: rodHoldActive === true,
      controlActive: controlActive === true,
      effectivePressureKg: nonNegativeOr(effectivePressureKg),
    });
  }
}
