export class OutcomeRenderFrameBuilder {
  #canvasMetrics;
  #clock;
  #styleResolver;
  #layoutResolver;
  #assetIdForSource;
  #resolveFishImage;
  #unknownRarity = Object.freeze({
    isResolved: false,
    halfSteps: 0,
    stars: 0,
    maxHalfSteps: 0,
    maxStars: 0,
    unitsPerStar: 2,
    weightBand: 0,
    weightBandCount: 0,
    levelMinWeightKg: null,
    levelMaxWeightKg: null,
    isMaximum: false,
  });
  #layoutContext = {
    width: 0,
    height: 0,
    config: null,
    statCount: 0,
  };

  constructor({
    canvasMetrics,
    clock,
    styleResolver,
    layoutResolver,
    assetIdForSource = null,
    resolveFishImage,
  }) {
    // The one victory image source (spec 100 D4), shared with the asset preloader; composed in bootstrap.
    if (typeof resolveFishImage !== "function") {
      throw new TypeError("OutcomeRenderFrameBuilder requires resolveFishImage");
    }
    if (!styleResolver || typeof styleResolver.resolveVictory !== "function") {
      throw new TypeError(
        "OutcomeRenderFrameBuilder requires styleResolver",
      );
    }
    if (!layoutResolver || typeof layoutResolver.resolve !== "function") {
      throw new TypeError(
        "OutcomeRenderFrameBuilder requires layoutResolver",
      );
    }
    this.#canvasMetrics = canvasMetrics;
    this.#clock = clock;
    this.#styleResolver = styleResolver;
    this.#layoutResolver = layoutResolver;
    this.#assetIdForSource = assetIdForSource || OutcomeRenderFrameBuilder.#defaultAssetIdForSource;
    this.#resolveFishImage = resolveFishImage;
  }

  buildInto({ target, intent }) {
    if (!intent.visible) return;
    target.visible = true;
    target.mode = intent.mode;
    if (intent.mode === "failed") {
      this.#buildGameOver(target.gameOver, intent.reason);
    } else if (intent.mode === "victory") {
      this.#buildVictory(target.victory, intent.fish || {}, intent.canLiveBait === true);
    }
  }

  #buildGameOver(target, reason) {
    let title = "LINE SNAPPED";
    let titleColor = "#ff4444";
    let description = "Tension exceeded line capacity.";
    if (reason === "rod") {
      title = "ROD BROKEN";
      titleColor = "#ff0000";
      description = "Your rod could not handle the stress.";
    } else if (reason === "reel") {
      title = "REEL FAILED";
      titleColor = "#ff2200";
      description = "The reel was the weakest part of the rig.";
    } else if (reason === "leader") {
      title = "LEADER SNAPPED";
      titleColor = "#ff6644";
      description = "The leader was the weakest part of the rig.";
    } else if (reason === "hook" || reason === "net_escape") {
      title = "FISH ESCAPED";
      titleColor = "#ffaa00";
      description =
        reason === "net_escape"
          ? "The fish was too heavy and broke out of the net!"
          : "The hook bent and the fish got away.";
    }
    target.visible = true;
    target.width = this.#canvasMetrics.width;
    target.height = this.#canvasMetrics.height;
    target.title = title;
    target.titleColor = titleColor;
    target.description = description;
  }

  #buildVictory(target, source, canLiveBait = false) {
    const fish = target.fish || (target.fish = {});
    const id = String(source.id || "unknown");
    const level = Number(source.level) || 1;
    const imagePath = this.#resolveFishImage(source);
    fish.id = id;
    fish.name = String(source.name || "Unknown fish");
    fish.level = level;
    fish.maxLevel = Number(source.maxLevel) || 0;
    fish.weight = Number(source.weight) || 0;
    fish.anomaly = String(source.anomaly || "none");
    fish.isTrophy = source.isTrophy === true;
    fish.isUnique = source.isUnique === true;
    fish.rarity = this.#resolveRarity(source, fish);
    const config = this.#styleResolver.resolveVictory();
    const stats = target.stats;
    this.#addStat(stats, `${fish.weight.toFixed(3)} kg`, null);
    this.#addStat(
      stats,
      fish.isTrophy ? "✓ Trophy" : "❌ Not trophy",
      null,
      fish.isTrophy ? null : "neutral",
    );
    this.#addStat(stats, `Anomaly: ${fish.anomaly}`, null);
    const extraStats = Array.isArray(source.victoryStats)
      ? source.victoryStats
      : [];
    for (let index = 0; index < extraStats.length; index += 1) {
      const stat = extraStats[index] || {};
      this.#addStat(
        stats,
        String(stat.label || stat.value || ""),
        stat.color || null,
      );
    }
    target.visible = true;
    target.width = this.#canvasMetrics.width;
    target.height = this.#canvasMetrics.height;
    target.nowMs = this.#clock.realNow ?? this.#clock.now;
    target.fish = fish;
    target.config = config;
    target.canLiveBait = canLiveBait;
    const layoutContext = this.#layoutContext;
    layoutContext.width = this.#canvasMetrics.width;
    layoutContext.height = this.#canvasMetrics.height;
    layoutContext.config = config;
    layoutContext.statCount = stats.count;
    layoutContext.canLiveBait = canLiveBait;
    target.layout = this.#layoutResolver.resolve(layoutContext);
    target.spriteId = this.#assetIdForSource(imagePath, "fish");
    target.spritePath = imagePath;
  }

  // Preserve the existing two-argument ID contract for callers without a platform capability.
  static #defaultAssetIdForSource(src, namespace = "asset") {
    const normalized = String(src || "").trim();
    return normalized ? `${namespace}:${normalized}` : "";
  }

  #resolveRarity(source, fish) {
    const rarity = source.rarity;
    if (rarity && Number.isFinite(Number(rarity.halfSteps))) {
      return rarity;
    }
    return this.#unknownRarity;
  }

  #addStat(target, label, color, tone = null) {
    const record = target.acquire();
    record.label = label;
    record.color = color;
    record.tone = tone;
  }
}
